// 1. 获取所有输入项目（这里应该是3张图）
const items = $input.all();

// 2. 遍历每一个项目
for (let i = 0; i < items.length; i++) {
  try {
    // 读取第 i 个项目的二进制数据
    // 注意：getBinaryDataBuffer 需要传入对应的 index
    const imageBuffer = await this.helpers.getBinaryDataBuffer(i, 'data');

    // 转换为 Base64 并存入 json 字段
    items[i].json.base64_content = imageBuffer.toString('base64');
  } catch (error) {
    // 防止某张图出错导致整体中断
    items[i].json.error = error.message;
  }
}

// 3. 返回所有处理好的项目
return items;

// 1. 获取 GitHub 节点的结果
const githubItems = $input.all();
// 2. 获取 Split Out 节点的原始数据 (找回 caption)
const originalItems = $("Split Out1").all();

return githubItems.map((item, index) => {
  return {
    json: {
      // 找回原始占位符 ID
      id: originalItems[index].json.id,
      // 找回原始图注
      caption: originalItems[index].json.caption,
      // 【直接使用 GitHub 返回的字段】
      // 确保你先修复了上面提到的文件名配置错误！
      final_url: item.json.content.download_url
    }
  };
});

// 1. 使用 n8n 官方原生方法安全读取二进制 Buffer (自动处理内存/磁盘差异)
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');

// 2. 将 Buffer 转换为 UTF-8 纯文本字符串
const briefText = binaryBuffer.toString('utf-8');

// 3. 继承 Trigger 传来的配置参数
const triggerData = $('Execute Workflow Trigger').first().json;

return {
  json: {
    ...triggerData,
    drive_markdown_content: briefText // 此时这里将是完美的 Markdown 明文
  }
};

const rawOutput = $input.first().json.output;

// 1. 提取 <FINAL_REWRITE> 标签内的纯净文本
const match = rawOutput.match(/<FINAL_REWRITE>([\s\S]*?)<\/FINAL_REWRITE>/);
let finalText = match ? match[1].trim() : rawOutput;

// 2. 修复中文语境下 Markdown 加粗前后的空格问题 (防止排版粘连)
finalText = finalText.replace(/([^\s\n])\*\*/g, '$1 **');
finalText = finalText.replace(/\*\*([^\s\n.,;:!?，。；：！？])/g, '** $1');

// 3. 拆除“事实脚手架”：精准抹除 [KB], [Web], [1], [2] 等无意义引用标记
// 正则解释：匹配可选的前置空格 \s*，接着匹配 [KB] 或 [Web] 或[纯数字]，忽略大小写 i，全局替换 g
finalText = finalText.replace(/\s*\[(KB|Web|\d+)\]/gi, '');

return { json: { final_article: finalText } };

