// 1. 获取业务主键与任务配置 (来自入口)
const triggerData = $('Execute Workflow Trigger').first().json;
const contentId = triggerData.content_id;
const taskConfig = triggerData.task_config || {};

// 2. 获取宣发物料与清洗后的正文 (来自提取节点)
const extractData = $('output_extractor').first().json;
const socialKit = extractData.social_kit || "未生成宣发物料";
const cleanedArticle = extractData.cleaned_article || "";

// 3. 获取 Google Drive 文件指针 (来自 GDrive 节点)
const driveData = $input.first().json;
const driveDraftId = driveData.id;
const driveDraftLink = driveData.webViewLink;

// ==========================================
// 🎯 新增逻辑：精准提取 H1 标题供下游 Browser Pilot 使用
// ==========================================
let articleTitle = $input.first().json.name;
// 正则解释：匹配多行模式(m)下，以 # 开头，后跟至少一个空格，然后捕获剩余所有字符直到行尾
const titleMatch = cleanedArticle.match(/^#\s+(.*)$/m); 

if (titleMatch && titleMatch[1]) {
    // 提取成功，并去除首尾可能多余的空格
    articleTitle = titleMatch[1].trim(); 
}

// 4. 组装标准出口契约 (Egress Contract)
return {
  json: {
    content_id: contentId,
    task_config: taskConfig,
    drive_draft_id: driveDraftId,
    drive_draft_link: driveDraftLink,
    social_kit: socialKit,
    cleaned_article: cleanedArticle,
    article_title: articleTitle  // 👈 新增：提取出的纯文本标题
  }
};

// 1. 获取大模型的原始输出
const item = $input.first();
if (!item.json || !item.json.output || typeof item.json.output !== 'string') {
  throw new Error("Input is missing or not a string");
}
const rawText = item.json.output;

// 2. 纯粹提取：精准剥离 XML 标签 (不做任何内容篡改)
const articleMatch = rawText.match(/<FINAL_ARTICLE>([\s\S]*?)<\/FINAL_ARTICLE>/i);
const finalArticle = articleMatch ? articleMatch[1].trim() : rawText.trim(); 

const kitMatch = rawText.match(/<SOCIAL_KIT>([\s\S]*?)<\/SOCIAL_KIT>/i);
const socialKit = kitMatch ? kitMatch[1].trim() : "未生成宣发物料"; 

// 3. 动态生成安全的文件名
// 寻找第一行非空的文本作为标题基础，并剔除特殊字符
const firstLine = finalArticle.split('\n').find(line => line.trim().length > 0) || 'Untitled';
const fileNameBase = firstLine.replace(/^(#+\s*)/, '').trim().substring(0, 80).replace(/[\\/:*?"<>|]/g, ''); 
const fullFileName = `${fileNameBase || 'Omni_Draft'}.md`;

// 4. 语种嗅探与 Google Drive 路由分配
let targetLanguage = 'zh-CN'; // 默认中文
try {
  const triggerData = $('Execute Workflow Trigger').first().json;
  if (triggerData && triggerData.task_config && triggerData.task_config.language) {
    targetLanguage = triggerData.task_config.language;
  }
} catch (e) {
  // 容错：如果测试时找不到 Trigger 节点，默认走中文逻辑
}

// ⚠️ 请在这里填入您真实的 Google Drive 文件夹 ID
const FOLDER_ID_ZH = '1oNAzXx1644KdqZ4drGdNGZZy4GEt53Ns'; 
const FOLDER_ID_EN = '1ksMavAWIO8Pxwnoj1kZQa_Qv9ewo42P0';       

const targetFolderId = targetLanguage.toLowerCase().includes('en') ? FOLDER_ID_EN : FOLDER_ID_ZH;

// 5. 组装 n8n 标准的二进制文件流 (原封不动地将 Markdown 转为 Buffer)
const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(finalArticle, 'utf-8'),
  fullFileName,
  'text/markdown'
);

// 6. 输出结构化载荷
return {
  json: {
    filename: fullFileName,
    social_kit: socialKit,
    target_folder_id: targetFolderId,
    cleaned_article: finalArticle
  },
  binary: {
    markdownFile: binaryData       
  }
};

const imgbbItems = $input.all();
const originalItems = $("Split Out1").all();

return imgbbItems.map((item, index) => {
  return {
    json: {
      id: originalItems[index].json.id,
      caption: originalItems[index].json.caption,
      final_url: item.json.data.url
    }
  };
});

